class RiverCourseBankTest{static EnvironmentMap make(int water){int n=256;var e=new EnvironmentMap(EnvironmentMap.filled(n*n,water+20));e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];for(int z=0;z<n;z++)for(int x=124;x<=132;x++){int i=z*n+x;e.height[i]=water-3;e.water[i]=water;e.river[i]=1;}var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVER_BANKS,0,0);node.values.put("courses",1.0);node.values.put("width",14.0);node.values.put("reach",256.0);RiverBanks.gradeValley(node,e,n,n,62,2024,0,0,()->false);return e;}public static void main(String[]a){var high=make(350);var low=make(68);int i=128*256+148;double upper=high.height[i]-350,lower=low.height[i]-68;if(upper<lower*1.5)throw new AssertionError("Headwater valley not steeper: "+upper+" / "+lower);int stone=0,fine=0;for(int z=0;z<256;z++)for(int x=133;x<138;x++){int j=z*256+x;if(high.material[j]==3||high.material[j]==12)stone++;if(low.material[j]==2||low.material[j]==5)fine++;}if(stone<200||fine<200)throw new AssertionError("Missing coarse-to-fine deposits: "+stone+" / "+fine);System.out.println("PASS: upper valley steeper than lower floodplain; rocky upland banks and fine downstream sediment");}}
